head.script:
scwin.onpageload = function() {
	// [printSeq(1=폴더 단계, 2=하위), menuId(빈값=폴더), menuNm, useYn, pathNm]
	var rows = [
		[1, "", "자주자용하는폴더", "", ""],
		[2, "0003080455", "메뉴관리^0003080455", "Y", "업무계시스템 > 고객지원 > 고객관리 > 메뉴관리"],
		[2, "0000220052", "환변동 등록마감^0000220052", "N", "업무계시스템 > 인수(파생/기타) > 헷지 > 환변동 등록마감 > 환변동 등록마감"],
		[2, "0000030007", "국가기본정보^0000030007", "N", "업무계시스템 > 신용정보 > 국가정보 > 국가기본정보"],
		[2, "0000124372", "재무이상치모형검토^0000124372", "N", "업무계시스템 > 신용정보 > 국내기업 > 재무이상치 점검시스템 > 재무이상치모형검토"],
		[2, "0000020016", "보험료지원기관관리^0000020016", "N", "업무계시스템 > 고객지원 > 보험료지원 > 보험료지원기관관리"],
		[2, "0000020012", "고객정보관리^0000020012", "N", "업무계시스템 > 고객지원 > 고객관리 > 고객정보관리"],
		[1, "", "화요일폴더", "", ""],
		[2, "0000020013", "고객계좌관리^0000020013", "N", "업무계시스템 > 고객지원 > 고객관리 > 고객계좌관리"],
		[2, "0000123322", "재보험^0000123322", "Y", ""]
	];
	var json = [];
	for (var i = 0; i < rows.length; i++) {
		json.push({
			"fvrtFldrNm": rows[i][1] == "" ? rows[i][2] : "",
			"menuId": rows[i][1],
			"printSeq": rows[i][0],
			"menuNm": rows[i][2],
			"useYn": rows[i][3],
			"pathNm": rows[i][4]
		});
	}
	PsnFuncMyMenuVO.setJSON(json);
};
scwin.grdMyMenuInfo_onbeforeedit = function(row, col, value) {
	var rowData = PsnFuncMyMenuVO.getDataRow(row);
	if (rowData.printSeq == 1 && rowData.menuId.length == 0) {
		return true;
	}
	return false;
};
scwin.displayFomatter = function(value) {
	var rowData = PsnFuncMyMenuVO.getMatchedJSON("menuNm", value);
	if (rowData.length == 0) {
		return value;
	}
	var delVal = "";
	if (rowData[0].menuId != "") {
		if (rowData[0].useYn == 'N') {
			delVal = "<a class=\"btn btn_del\"></a>";
		}
		value = value.split('^')[0];
		value = delVal + value + "<w2:anchor class=\"btn_leftarea path\" outerDiv=\"false\" title=\"" + rowData[0].pathNm + "\">\"";
	} else {
		value = delVal + "<strong>" + value + "</strong>";
	}
	return value;
};
scwin.grdMyMenuInfo_onafteredit = function(row, col, value) {
	if (value == "") {
		console.error("폴더명을 입력하세요.");
		return false;
	}
};
